from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeResult, DocumentLineItem
from azure.core.credentials import AzureKeyCredential
import os
from typing import List, Dict, Any

def extract_receipt_data(receipt_file_path: str) -> Dict[str, Any]:
    """
    Extracts merchant, tax, total, and items from a receipt using Azure Document Intelligence.

    Args:
        receipt_file_path (str): The path to the receipt image or PDF file.

    Returns:
        Dict[str, Any]: A dictionary containing the extracted data.
    """
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    with open(receipt_file_path, "rb") as f:
        poller = document_intelligence_client.begin_analyze_document(
            "prebuilt-invoice", f, content_type="application/octet-stream"
        )
        invoices: AnalyzeResult = poller.result()

    extracted_data = {
        "merchant": None,
        "tax": None,
        "total": None,
        "items": []
    }

    if invoices.documents:
        # Assuming the first document is the relevant invoice/receipt
        invoice = invoices.documents[0]

        if invoice.fields:
            # Extract Merchant
            if "VendorName" in invoice.fields and invoice.fields["VendorName"].value:
                extracted_data["merchant"] = invoice.fields["VendorName"].value

            # Extract Total Tax
            if "TotalTax" in invoice.fields and invoice.fields["TotalTax"].value:
                extracted_data["tax"] = invoice.fields["TotalTax"].value

            # Extract Total Due
            if "InvoiceTotal" in invoice.fields and invoice.fields["InvoiceTotal"].value:
                extracted_data["total"] = invoice.fields["InvoiceTotal"].value
            elif "TotalDue" in invoice.fields and invoice.fields["TotalDue"].value:
                extracted_data["total"] = invoice.fields["TotalDue"].value


            # Extract Items
            if "Items" in invoice.fields and invoice.fields["Items"].value:
                for item_field in invoice.fields["Items"].value:
                    if item_field.value:
                        item_data = {}
                        if "Description" in item_field.value and item_field.value["Description"].value:
                            item_data["description"] = item_field.value["Description"].value
                        if "Amount" in item_field.value and item_field.value["Amount"].value:
                            item_data["amount"] = item_field.value["Amount"].value
                        elif "TotalPrice" in item_field.value and item_field.value["TotalPrice"].value:
                            item_data["amount"] = item_field.value["TotalPrice"].value
                        if "Quantity" in item_field.value and item_field.value["Quantity"].value:
                            item_data["quantity"] = item_field.value["Quantity"].value

                        if item_data: # Only add if some data was extracted for the item
                            extracted_data["items"].append(item_data)

    return extracted_data
